// Exemplu export CSV din C++
void exportCSV(Produs lista[], int n) {
    ofstream f("date.csv");
    f << "ID,Nume,Pret\n";  // header
    for(int i = 0; i < n; i++) {
        f << lista[i].id << ","
          << lista[i].nume << ","
          << lista[i].pret << "\n";
    }
    f.close();
    cout << "Export realizat in date.csv\n";
}
